with
quarantined as (
    select
        deal_source_system,
        deal_identity_key,
        deal_normalised_name,
        deal_external_id,
        deal_business_key,
        deal_target_company_external_id,
        deal_converted_fund_external_id,
        deal_record_id,
        deal_name,
        deal_strategy,
        deal_originating_team,
        deal_channel,
        deal_sourced_on,
        deal_structure,
        deal_converted_record_type,
        deal_company_business_key,
        deal_fund_business_key,
        deal_external_identity,
        violation_00,
        violation_01
    from {{ ref("investment__deal_vault__checked_post") }}
),
violations as (
    select
        'deal_business_key_not_null' as rule_name,
        deal_source_system,
        deal_identity_key,
        deal_normalised_name,
        deal_external_id,
        deal_business_key,
        deal_target_company_external_id,
        deal_converted_fund_external_id,
        deal_record_id,
        deal_name,
        deal_strategy,
        deal_originating_team,
        deal_channel,
        deal_sourced_on,
        deal_structure,
        deal_converted_record_type,
        deal_company_business_key,
        deal_fund_business_key,
        deal_external_identity
    from quarantined
    where violation_00

    union all

    select
        'deal_business_key_unique' as rule_name,
        deal_source_system,
        deal_identity_key,
        deal_normalised_name,
        deal_external_id,
        deal_business_key,
        deal_target_company_external_id,
        deal_converted_fund_external_id,
        deal_record_id,
        deal_name,
        deal_strategy,
        deal_originating_team,
        deal_channel,
        deal_sourced_on,
        deal_structure,
        deal_converted_record_type,
        deal_company_business_key,
        deal_fund_business_key,
        deal_external_identity
    from quarantined
    where violation_01
)

select
    rule_name,
    deal_source_system,
    deal_identity_key,
    deal_normalised_name,
    deal_external_id,
    deal_business_key,
    deal_target_company_external_id,
